import itertools

def reachable(perm):
    n=len(perm)
    pts=[(i+1,perm[i]) for i in range(n)]
    comp=[[False]*n for _ in range(n)]
    for i,(x1,y1) in enumerate(pts):
        for j,(x2,y2) in enumerate(pts):
            if i==j: continue
            comp[i][j]=(x1<x2 and y1<y2) or (x1>x2 and y1>y2)
    from collections import deque
    start=tuple(range(n))
    vis={start}
    q=deque([start])
    while q:
        S=q.popleft(); m=len(S)
        for idx,k in enumerate(S):
            T=tuple(i for i in S if not comp[k][i])
            if T not in vis:
                vis.add(T); q.append(T)
    return vis

def antichain_sets(perm):
    n=len(perm)
    pts=[(i+1,perm[i]) for i in range(n)]
    comp=[[False]*n for _ in range(n)]
    for i,(x1,y1) in enumerate(pts):
        for j,(x2,y2) in enumerate(pts):
            if i==j: continue
            comp[i][j]=(x1<x2 and y1<y2) or (x1>x2 and y1>y2)
    outs=set()
    for mask in range(1<<n):
        P=[i for i in range(n) if mask>>i&1]
        ok=True
        for a,b in itertools.combinations(P,2):
            if comp[a][b] or comp[b][a]: ok=False
        if not ok: continue
        T=tuple(i for i in range(n) if all(not comp[p][i] for p in P))
        outs.add(T)
    return outs

