import sys
sys.setrecursionlimit(1_000_000)

MOD = 998244353


def main() -> None:
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    A = [int(next(it)) - 1 for _ in range(N)]

    # Build graph and reverse graph
    g = [[] for _ in range(N)]
    rg = [[] for _ in range(N)]
    for i, to in enumerate(A):
        g[i].append(to)
        rg[to].append(i)

    # Kosaraju: 1st pass order
    used = [False] * N
    order = []

    def dfs1(v: int) -> None:
        used[v] = True
        for to in g[v]:
            if not used[to]:
                dfs1(to)
        order.append(v)

    for v in range(N):
        if not used[v]:
            dfs1(v)

    # Kosaraju: 2nd pass components
    comp = [-1] * N
    comps = []

    def dfs2(v: int, cid: int) -> None:
        comp[v] = cid
        comps[cid].append(v)
        for to in rg[v]:
            if comp[to] == -1:
                dfs2(to, cid)

    cid = 0
    for v in reversed(order):
        if comp[v] == -1:
            comps.append([])
            dfs2(v, cid)
            cid += 1

    K = cid

    # Condensed graph is a forest with edges child -> parent
    parent = [-1] * K
    children = [[] for _ in range(K)]

    for i in range(N):
        ci = comp[i]
        cj = comp[A[i]]
        if ci != cj:
            parent[ci] = cj

    for v in range(K):
        p = parent[v]
        if p != -1:
            children[p].append(v)

    # DP on condensed trees:
    # f_v[t] = ways in subtree of v with value(v)=t
    # f_v[t] = product over children c of (sum_{s<=t} f_c[s])
    def solve_node(v: int):
        arr = [1] * (M + 1)  # arr[t], t=1..M
        for c in children[v]:
            fc = solve_node(c)
            pref = 0
            for t in range(1, M + 1):
                pref += fc[t]
                if pref >= MOD:
                    pref -= MOD
                arr[t] = (arr[t] * pref) % MOD
        return arr

    ans = 1
    for v in range(K):
        if parent[v] == -1:
            fv = solve_node(v)
            total = sum(fv[1:]) % MOD
            ans = (ans * total) % MOD

    print(ans)


if __name__ == "__main__":
    main()

