                    is_prime[j] = False

    ans = 1

    for p in primes:
        exps = [0] * (N - 1)
        total = 0

        # exponent of prime p in each A_i
        for i, x in enumerate(A):
            c = 0
            while x % p == 0:
                x //= p
                c += 1
            exps[i] = c
            total += c

        if total == 0:
            continue

        S = total
        H = 2 * S
        q = p % MOD

        # q^h for 0..H
        pw = [1] * (H + 1)
        for h in range(1, H + 1):
            pw[h] = (pw[h - 1] * q) % MOD

        # DP over shifted height z >= 0
        # nt: paths that have not touched 0 yet
        # tt: paths that have touched 0 at least once
        nt = [0] * (H + 1)
        tt = [0] * (H + 1)

        # initial start height c (0..S), weight q^c (includes vertex 1 contribution)
        tt[0] = 1
        for c in range(1, S + 1):
            nt[c] = pw[c]

        for a in exps:
            nnt = [0] * (H + 1)
            ntt = [0] * (H + 1)

            if a == 0:
                # only stay in place
                for h in range(H + 1):
                    v0 = nt[h]
                    v1 = tt[h]
                    if v0:
                        add = v0 * pw[h] % MOD
                        if h == 0:
                            ntt[0] = (ntt[0] + add) % MOD
                        else:
                            nnt[h] = (nnt[h] + add) % MOD
                    if v1:
                        ntt[h] = (ntt[h] + v1 * pw[h]) % MOD
            else:
                for h in range(H + 1):
                    v0 = nt[h]
                    v1 = tt[h]
                    if not v0 and not v1:
                        continue

                    hu = h + a
                    if hu <= H:
                        w = pw[hu]
                        if v0:
                            nnt[hu] = (nnt[hu] + v0 * w) % MOD
                        if v1:
                            ntt[hu] = (ntt[hu] + v1 * w) % MOD

                    hd = h - a
                    if hd >= 0:
                        w = pw[hd]
                        if v0:
                            if hd == 0:
                                ntt[0] = (ntt[0] + v0 * w) % MOD
                            else:
                                nnt[hd] = (nnt[hd] + v0 * w) % MOD
                        if v1:
                            ntt[hd] = (ntt[hd] + v1 * w) % MOD

            nt, tt = nnt, ntt

        Fp = sum(tt) % MOD
        ans = (ans * Fp) % MOD

    print(ans)

