import sys

MOD = 998244353

def main():
    input = sys.stdin.readline
    N = int(input())
    A = list(map(int, input().split()))

    maxA = max(A)

    # Euler's totient for all 1..maxA
    phi = list(range(maxA + 1))
    for p in range(2, maxA + 1):
        if phi[p] == p:  # prime
            for k in range(p, maxA + 1, p):
                phi[k] -= phi[k] // p

    # divisors[x] = list of all positive divisors of x
    divisors = [[] for _ in range(maxA + 1)]
    for d in range(1, maxA + 1):
        for m in range(d, maxA + 1, d):
            divisors[m].append(d)

    S = [0] * (maxA + 1)  # S[d] = sum of weights 2^{i-1} for previous A_i divisible by d

    ans = 0
    w = 1  # 2^{i-1}
    out = []

    for a in A:
        f = 0
        for d in divisors[a]:
            f += phi[d] * S[d]
        f %= MOD

        ans = (2 * ans + f) % MOD
        out.append(str(ans))

        for d in divisors[a]:
            S[d] += w
            if S[d] >= MOD:
                S[d] -= MOD

        w <<= 1
        if w >= MOD:
            w -= MOD

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()

