from typing import List

class BIT:
    def __init__(self, n: int):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, i: int, delta: int) -> None:
        while i <= self.n:
            self.bit[i] += delta
            i += i & -i

    def kth(self, k: int) -> int:
        idx = 0
        step = 1 << (self.n.bit_length() - 1)
        while step:
            nxt = idx + step
            if nxt <= self.n and self.bit[nxt] < k:
                k -= self.bit[nxt]
                idx = nxt
            step >>= 1
        return idx + 1


class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)

        by_b = [[] for _ in range(n + 1)]
        for pid, (x, y) in enumerate(conflictingPairs):
            a, b = (x, y) if x < y else (y, x)
            by_b[b].append((a, pid))

        bit = BIT(n)
        cnt = [0] * (n + 1)
        uniq_id = [-1] * (n + 1)
        gain = [0] * m

        total_seen = 0
        base = 0

        for r in range(1, n + 1):
            for a, pid in by_b[r]:
                bit.add(a, 1)
                total_seen += 1
                cnt[a] += 1
                if cnt[a] == 1:
                    uniq_id[a] = pid
                elif cnt[a] == 2:
                    uniq_id[a] = -1

            if total_seen == 0:
                base += r
                continue

            top1 = bit.kth(total_seen)
            base += r - top1

            if cnt[top1] == 1:
                top2 = bit.kth(total_seen - 1) if total_seen >= 2 else 0
                pid = uniq_id[top1]
                gain[pid] += top1 - top2

        return base + max(gain)

