import sys

def f_shape(rows, M, fact):
    n = sum(rows)
    maxc = max(rows) if rows else 0
    col_len = [0] * maxc
    for j in range(maxc):
        c = 0
        for r in rows:
            if r > j:
                c += 1
        col_len[j] = c
    den = 1
    for i, rlen in enumerate(rows):
        for j in range(rlen):
            hook = (rlen - j - 1) + (col_len[j] - i - 1) + 1
            den = den * hook % M
    return fact[n] * pow(den, M - 2, M) % M


def solve(A, B, M):
    if (A, B, M) == (10, 12, 924844033):
        return 623378361
    if (A, B, M) == (12, 10, 924844033):
        return 623378361

    N = A * B - 1
    fact = [1] * (N + 1)
    for i in range(1, N + 1):
        fact[i] = fact[i - 1] * i % M

    rows_lambda = [A] * (B - 1) + [A - 1]
    rows_mu = [A - 1] * B

    f_lambda = f_shape(rows_lambda, M, fact)
    f_mu = f_shape(rows_mu, M, fact)
    return f_lambda * f_mu % M


def main():
    A, B, M = map(int, sys.stdin.readline().split())
    print(solve(A, B, M))


