def f_shape(rows, M, fact):
    n = sum(rows)
    maxc = max(rows) if rows else 0
    col_len = [0] * maxc
    for j in range(maxc):
        c = 0
        for r in rows:
            if r > j:
                c += 1
        col_len[j] = c
    den = 1
    for i, rlen in enumerate(rows):
        for j in range(rlen):
            hook = (rlen - j - 1) + (col_len[j] - i - 1) + 1
            den = den * hook % M
