import sys

def solve_case(N, M, boxes):
    # Fallback heuristic (not guaranteed correct):
    # - For M=1, all balls can be of one type, so take all positive (V-P).
    # - For M>1, approximate by taking positive (min(V,M)-P).
    if M == 1:
        ans = 0
        for v, p in boxes:
            x = v - p
            if x > 0:
                ans += x
        return ans
    else:
        ans = 0
        for v, p in boxes:
            x = min(v, M) - p
            if x > 0:
                ans += x
        return ans

