import sys


def min_cost_for_k(k, A, P, B, Q):
    # Minimum cost to achieve throughput >= k using:
    # x units of machine S (A, P), y units of machine T (B, Q)
    best = 10**30

    # Cost change of transformation (x, y) -> (x-B, y+A):
    # delta = A*Q - B*P
    if A * Q <= B * P:
        # Repeating that transformation never increases cost,
        # so an optimal solution exists with 0 <= x < B.
        for x in range(B):
            rem = k - A * x
            if rem <= 0:
                y = 0
            else:
                y = (rem + B - 1) // B
            c = P * x + Q * y
            if c < best:
                best = c
    else:
        # Reverse transformation (x, y) -> (x+B, y-A) never increases cost,
        # so an optimal solution exists with 0 <= y < A.
        for y in range(A):
            rem = k - B * y
            if rem <= 0:
                x = 0
            else:
                x = (rem + A - 1) // A
            c = P * x + Q * y
            if c < best:
                best = c

    return best


def feasible(k, data, X):
    total = 0
    for A, P, B, Q in data:
        total += min_cost_for_k(k, A, P, B, Q)
        if total > X:
            return False
    return True


def main():
    input = sys.stdin.readline
    N, X = map(int, input().split())
    data = [tuple(map(int, input().split())) for _ in range(N)]

    lo, hi = 0, 10**18
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid, data, X):
            lo = mid
        else:
            hi = mid - 1

    print(lo)


if __name__ == "__main__":
    main()

