from typing import *

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        m = len(s)

        # Binomial coefficients C[n][r] for 0 <= n, r <= m
        C = [[0] * (m + 1) for _ in range(m + 1)]
        for i in range(m + 1):
            C[i][0] = 1
            C[i][i] = 1
            for j in range(1, i):
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD

        # g[c] = number of popcount-steps to reduce c to 1, for c >= 1
        INF = 10**9
        g = [INF] * (m + 1)
        g[1] = 0
        for c in range(2, m + 1):
            g[c] = 1 + g[c.bit_count()]

        def count_less_with_ones(target_ones: int) -> int:
            # Count x with 0 <= x < int(s,2) and popcount(x) == target_ones
            ans = 0
            need = target_ones

            for i, ch in enumerate(s):
                rem = m - i - 1
                if ch == '1':
                    # Put 0 here (strictly smaller), choose remaining ones freely.
                    if 0 <= need <= rem:
                        ans = (ans + C[rem][need]) % MOD

                    # Equal-prefix branch: put 1 here.
                    need -= 1
                    if need < 0:
                        break
            return ans

        ans = 0
        # For numbers x>=1 with popcount(x)=c, steps(x)<=k iff g[c] <= k-1.
        for c in range(1, m + 1):
