            rx=find(x)
            if t=='U':
                u,v=ra,rx
            else:
                u,v=rx,ra
            if u==v: return False
            edges.append((u,v))
    # compress nodes
    reps={find(i) for i in range(N)}
    idx={r:i for i,r in enumerate(reps)}
    g=[[] for _ in reps]; indeg=[0]*len(reps)
    for u,v in edges:
        u=idx[u];v=idx[v]
        g[u].append(v); indeg[v]+=1
