        print(0 if A == B else -1)
        return

    # Lifted formulation:
    # Final lifted values are X_i = B_i + M*(p_i + c).
    # p_i is determined by adjacent-order invariants, c is a global integer shift.
    p = 0
    y = []  # y_i = B_i + M*p_i - A_i

    for i in range(N):
        y.append(B[i] + M * p - A[i])
        if i + 1 < N:
            a_up = A[i + 1] > A[i]
            b_up = B[i + 1] > B[i]
            if a_up:
                if not b_up:
                    p += 1
            else:
                if b_up:
                    p -= 1

    # Minimize f(c) = sum |M*c + y_i| over integer c.
    # It's convex; optimum is around median of -y_i.
    u = sorted(-v for v in y)
    med1 = u[(N - 1) // 2]
    med2 = u[N // 2]

