    # NOTE: exact brute force for tiny instances only.
    if N <= 10 and K <= 6:
        ans = 0
        all_words = list(product(range(1, K+1), repeat=M))
        for A in product(range(1, K+1), repeat=N):
            miss = []
            for w in all_words:
                if not is_subseq(A, w):
                    miss.append(w)
                    if len(miss) >= 2:
                        break
            if len(miss) == 1 and miss[0] == X:
                ans += 1
        print(ans % MOD)
        return

    # Fallback (not intended for large constraints).
    print(0)

