class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2

        pow10 = [1 % k] * n
        for i in range(1, n):
            pow10[i] = (pow10[i - 1] * 10) % k

        coeff = [0] * m
        for j in range(m):
            a = pow10[j]
            b = pow10[n - 1 - j]
            if j == n - 1 - j:
                coeff[j] = a
            else:
                coeff[j] = (a + b) % k

        masks = [0] * (m + 1)
        masks[m] = 1  # residue 0 reachable with no remaining digits

        for i in range(m - 1, -1, -1):
            next_mask = masks[i + 1]
            cur = 0
            start = 1 if i == 0 else 0
            c = coeff[i]
            for d in range(start, 10):
                add = (d * c) % k
                for r in range(k):
                    if (next_mask >> r) & 1:
                        cur |= 1 << ((add + r) % k)
            masks[i] = cur

        first_half = []
        prefix_mod = 0
        for i in range(m):
            start = 1 if i == 0 else 0
            c = coeff[i]
            next_mask = masks[i + 1]
            for d in range(9, start - 1, -1):
                need = (-(prefix_mod + d * c)) % k
                if (next_mask >> need) & 1:
                    first_half.append(str(d))
                    prefix_mod = (prefix_mod + d * c) % k
                    break

        left = ''.join(first_half)
        return left + left[: n // 2][::-1]

