    dp={0:0}
    for i in range(m):
        ndp={}
        for xin,val in dp.items():
            maxout=B
            for xout in range(maxout+1 if i<m-1 else 1):
                r=c[i]+xin-xout
                cost=val + (xout if i<m-1 else 0) + abs(r-t[i])
                if i==m-1 and xout!=0: continue
