class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w))
            adj[v].append((u, w))

        parent = [-1] * n
        parent[0] = 0
        order = [0]

        for u in order:
            for v, _ in adj[u]:
                if parent[v] == -1:
                    parent[v] = u
                    order.append(v)

        dp0 = [0] * n  # parent edge not used
        dp1 = [0] * n  # parent edge used

        for u in reversed(order):
            base = 0
            gains = []
            for v, w in adj[u]:
                if v == parent[u]:
                    continue
                base += dp0[v]
                gain = w + dp1[v] - dp0[v]
                if gain > 0:
                    gains.append(gain)

            gains.sort(reverse=True)

            take0 = min(k, len(gains))
            best0 = base
            for i in range(take0):
                best0 += gains[i]
            dp0[u] = best0

            cap1 = k - 1
            best1 = base
            if cap1 > 0:
                take1 = min(cap1, len(gains))
                for i in range(take1):
                    best1 += gains[i]
            dp1[u] = best1

        return dp0[0]

