import sys

def min_ops(A: str, B: str) -> int:
    posa = [i for i, c in enumerate(A) if c == '1']
    posb = [i for i, c in enumerate(B) if c == '1']
    m, k = len(posa), len(posb)
    if k > m:
        return -1

    def feasible(t: int) -> bool:
        # Greedy injective matching from B-ones to A-pieces with |pos diff| <= t
        i = 0
        for b in posb:
            while i < m and posa[i] < b - t:
                i += 1
            if i == m or posa[i] > b + t:
                return False
            i += 1
        return True

    lo, hi = 0, len(A)
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1

    return lo if feasible(lo) else -1


