def build_rev(P):
    n=len(P)
    # fenwick for empties
    bit=[0]*(n+1)
    def add(i,v):
        while i<=n:
            bit[i]+=v;i+=i&-i
    def kth(k):
        i=0; b=1<<(n.bit_length()-1)
        while b:
            ni=i+b
            if ni<=n and bit[ni]<k:
                k-=bit[ni]; i=ni
            b>>=1
        return i+1
    for i in range(1,n+1): add(i,1)
    ans=[0]*n
    for i in range(n,0,-1):
        pos=kth(P[i-1])
        ans[pos-1]=i
        add(pos,-1)
    return ans

