from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        INF = 10**30
        min_prefix = [INF] * k

        prefix_sum = 0
        best = -10**30

        # r is prefix index: subarray is [l, r), length = r - l
        for r in range(len(nums) + 1):
            if r > 0:
                prefix_sum += nums[r - 1]

            rem = r % k

            # Use the smallest prefix sum seen before with the same remainder
            # to maximize prefix_sum - previous_prefix_sum.
            if min_prefix[rem] != INF:
                best = max(best, prefix_sum - min_prefix[rem])

            # Make current prefix available for future r's.
            if prefix_sum < min_prefix[rem]:
                min_prefix[rem] = prefix_sum

        return best

