import math
from bisect import bisect_right


def sieve(n: int):
    if n < 2:
        return []
    is_prime = bytearray(b"\x01") * (n + 1)
    is_prime[0:2] = b"\x00\x00"
    limit = int(n ** 0.5)
    for p in range(2, limit + 1):
        if is_prime[p]:
            start = p * p
            is_prime[start:n + 1:p] = b"\x00" * (((n - start) // p) + 1)
    return [i for i in range(2, n + 1) if is_prime[i]]


def floor_kth_root(n: int, k: int) -> int:
    if n <= 1:
        return n
    x = int(n ** (1.0 / k))
    while (x + 1) ** k <= n:
        x += 1
    while x ** k > n:
        x -= 1
    return x


def main() -> None:
    N = int(sys.stdin.readline().strip())

    # For p^2 q^2, we need primes up to sqrt(N)
    S = math.isqrt(N)
    primes = sieve(S)

    # 1) Numbers of the form p^8
    r8 = floor_kth_root(N, 8)
    ans = bisect_right(primes, r8)

    # 2) Numbers of the form p^2 q^2 (p < q), equivalent to p*q <= sqrt(N)
    j = len(primes) - 1
    for i, p in enumerate(primes):
        if i >= j:
            break
        while i < j and p * primes[j] > S:
            j -= 1
        if j <= i:
            break
        ans += j - i

    print(ans)


if __name__ == "__main__":
    main()

