import random, math

def fast(N):
    def sieve(n):
        if n<2:return []
        is_prime=bytearray(b'\x01')*(n+1)
        is_prime[0:2]=b'\x00\x00'
        for p in range(2,int(n**0.5)+1):
            if is_prime[p]:
                st=p*p
                is_prime[st:n+1:p]=b'\x00'*(((n-st)//p)+1)
        return [i for i in range(2,n+1) if is_prime[i]]
    def floor_kth_root(n,k):
        if n<=1:return n
        x=int(n**(1.0/k))
        while (x+1)**k<=n:x+=1
        while x**k>n:x-=1
        return x
    S=math.isqrt(N)
    primes=sieve(S)
    import bisect
    ans=bisect.bisect_right(primes,floor_kth_root(N,8))
    j=len(primes)-1
    for i,p in enumerate(primes):
        if i>=j: break
        while i<j and p*primes[j]>S:
            j-=1
        if j<=i: break
        ans += j-i
    return ans

def naive(N):
    c=0
    for x in range(1,N+1):
        d=0
        r=int(x**0.5)
        for i in range(1,r+1):
            if x%i==0:
                d+=2
        if r*r==x:d-=1
        if d==9:c+=1
    return c

for N in [1,10,50,100,200,500,1000,5000,10000]:
    a,b=fast(N),naive(N)
    print(N,a,b,a==b)

