from itertools import permutations

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)

    N = next(it)

    MG = next(it)
    G = [[0] * N for _ in range(N)]
    for _ in range(MG):
        u = next(it) - 1
        v = next(it) - 1
        G[u][v] = G[v][u] = 1

    MH = next(it)
    H = [[0] * N for _ in range(N)]
    for _ in range(MH):
        a = next(it) - 1
        b = next(it) - 1
        H[a][b] = H[b][a] = 1

    A = [[0] * N for _ in range(N)]
    for i in range(N - 1):
        for j in range(i + 1, N):
            c = next(it)
            A[i][j] = A[j][i] = c

    ans = 10**30
    vertices = list(range(N))

    # p[i] := vertex in H corresponding to vertex i in G
    for p in permutations(vertices):
        cost = 0
        for i in range(N - 1):
            pi = p[i]
            Gi = G[i]
            for j in range(i + 1, N):
                if Gi[j] != H[pi][p[j]]:
                    cost += A[pi][p[j]]
                    if cost >= ans:
                        break
            if cost >= ans:
                break
        if cost < ans:
            ans = cost

    print(ans)

if __name__ == "__main__":
