def brute(nums):
    n=len(nums)
    dp=[-10**18]*n
    dp[0]=0
    for j in range(1,n):
        best=-10**18
        for i in range(j):
            best=max(best,dp[i]+(j-i)*nums[i])
        dp[j]=best
    return dp[-1]

