from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)

        # For each index i, bitsets[i] stores achievable total decrements for nums[i].
        # Bit s = 1 means sum s is achievable.
        bitsets = [1] * n
        masks = [(1 << (x + 1)) - 1 for x in nums]  # keep only bits up to nums[i]

        done = [x == 0 for x in nums]
        unsatisfied = sum(0 if d else 1 for d in done)

        if unsatisfied == 0:
            return 0

        for k, (l, r, val) in enumerate(queries, 1):
            for i in range(l, r + 1):
                if done[i]:
                    continue

                b = bitsets[i]
                # 0/1 subset-sum transition with item value = val
                nb = b | ((b << val) & masks[i])
                bitsets[i] = nb

                if (nb >> nums[i]) & 1:
                    done[i] = True
                    unsatisfied -= 1

            if unsatisfied == 0:
                return k

        return -1

