import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        s_n = str(n)
        s_m = str(m)
        if len(s_n) != len(s_m):
            return -1

        L = len(s_n)
        LIMIT = 10 ** L

        # Sieve of Eratosthenes for primality checks up to LIMIT - 1.
        is_prime = [True] * LIMIT
        if LIMIT > 0:
            is_prime[0] = False
        if LIMIT > 1:
            is_prime[1] = False

        p = 2
        while p * p < LIMIT:
            if is_prime[p]:
                start = p * p
                step = p
                is_prime[start:LIMIT:step] = [False] * (((LIMIT - 1 - start) // step) + 1)
            p += 1

        # n must be non-prime initially, and m must be non-prime at the end.
        if is_prime[n] or is_prime[m]:
            return -1

        INF = 10**30
        dist = [INF] * LIMIT
        dist[n] = n  # cost includes the initial value

        pq = [(n, n)]  # (current_cost, value)
        places = [10 ** i for i in range(L)]

        while pq:
            cur_cost, x = heapq.heappop(pq)
            if cur_cost != dist[x]:
                continue
            if x == m:
                return cur_cost

            for place in places:
                digit = (x // place) % 10

                # Increase this digit
                if digit < 9:
                    y = x + place
                    if not is_prime[y]:
                        new_cost = cur_cost + y
                        if new_cost < dist[y]:
                            dist[y] = new_cost
                            heapq.heappush(pq, (new_cost, y))

                # Decrease this digit
                if digit > 0:
                    y = x - place
                    if not is_prime[y]:
                        new_cost = cur_cost + y
                        if new_cost < dist[y]:
                            dist[y] = new_cost
                            heapq.heappush(pq, (new_cost, y))

        return -1

