from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)

        is_target = [0] * n
        for idx in targetIndices:
            is_target[idx] = 1

        INF = 10**9
        dp = [INF] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            keep_cost = is_target[i]
            # Reverse iteration: each source character can extend at most one next state
            for j in range(m - 1, -1, -1):
                if pattern[j] == ch and dp[j] != INF:
                    cand = dp[j] + keep_cost
                    if cand < dp[j + 1]:
                        dp[j + 1] = cand

        min_kept_targets = dp[m]
        return len(targetIndices) - min_kept_targets

