class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        rev=[[] for _ in range(n)]
        ws=[]
        for a,b,w in edges:
            rev[b].append((a,w))
            ws.append(w)
        def ok(mx:int)->bool:
            vis=[False]*n
            q=deque([0]); vis[0]=True; cnt=1
            while q:
                u=q.popleft()
                for v,w in rev[u]:
                    if w<=mx and not vis[v]:
                        vis[v]=True; cnt+=1; q.append(v)
            return cnt==n
        if not ok(10**6):
            return -1
        uniq=sorted(set(ws))
        lo,hi=0,len(uniq)-1
        ans=uniq[-1]
        while lo<=hi:
            mid=(lo+hi)//2
            if ok(uniq[mid]):
                ans=uniq[mid]; hi=mid-1
            else:
                lo=mid+1
        return ans

