from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        m = n // 2
        INF = 10**30

        # dp[a][b]: min cost after processing pairs up to current k,
        # where left house color is a and right house color is b.
        dp = [[INF] * 3 for _ in range(3)]

        # Initialize with outermost pair (0, n-1)
        for a in range(3):
            for b in range(3):
                if a != b:  # equidistant constraint
                    dp[a][b] = cost[0][a] + cost[n - 1][b]

        # Process pairs inward
        for k in range(1, m):
            ndp = [[INF] * 3 for _ in range(3)]
            left_idx = k
            right_idx = n - 1 - k

            for prev_left_color in range(3):
                for prev_right_color in range(3):
                    cur = dp[prev_left_color][prev_right_color]
                    if cur >= INF:
                        continue

                    for left_color in range(3):
                        if left_color == prev_left_color:  # adjacent on left side
                            continue
                        for right_color in range(3):
                            if right_color == prev_right_color:  # adjacent on right side
                                continue
                            if right_color == left_color:  # equidistant pair constraint
                                continue

                            val = cur + cost[left_idx][left_color] + cost[right_idx][right_color]
                            if val < ndp[left_color][right_color]:
                                ndp[left_color][right_color] = val

            dp = ndp

        return min(min(row) for row in dp)

