import sys

def main():
    input = sys.stdin.readline
    N, W = map(int, input().split())

    cols = [[] for _ in range(W)]
    rank = [0] * (N + 1)

    for i in range(1, N + 1):
        x, y = map(int, input().split())
        cols[x - 1].append((y, i))

    min_cnt = 10**18
    for c in cols:
        c.sort()
        if len(c) < min_cnt:
            min_cnt = len(c)
        for r, (_, idx) in enumerate(c, 1):
            rank[idx] = r

