class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = set('aeiou')
        n = len(word)
        ans = 0

        for i in range(n):
            counts = {v: 0 for v in vowels}
            have = 0
            consonants = 0

            for j in range(i, n):
                ch = word[j]
                if ch in vowels:
                    if counts[ch] == 0:
                        have += 1
                    counts[ch] += 1
                else:
                    consonants += 1

                if consonants > k:
                    break

                if consonants == k and have == 5:
                    ans += 1

        return ans

