from typing import List

class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        pts = [tuple(p) for p in points]
        point_set = set(pts)
        n = len(pts)
        best = -1

        # Try every pair as opposite corners (diagonal) of an axis-aligned rectangle
        for i in range(n):
            x1, y1 = pts[i]
            for j in range(i + 1, n):
                x2, y2 = pts[j]

                # Same x or same y => zero area, not a valid rectangle
                if x1 == x2 or y1 == y2:
                    continue

                left, right = (x1, x2) if x1 < x2 else (x2, x1)
                bottom, top = (y1, y2) if y1 < y2 else (y2, y1)

                c1 = (left, bottom)
                c2 = (left, top)
                c3 = (right, bottom)
                c4 = (right, top)

                # All four corners must exist
                if c1 not in point_set or c2 not in point_set or c3 not in point_set or c4 not in point_set:
                    continue

                corners = {c1, c2, c3, c4}

                # No other point may lie inside or on border of the rectangle
                valid = True
                for x, y in pts:
                    if (x, y) in corners:
                        continue
                    if left <= x <= right and bottom <= y <= top:
                        valid = False
                        break

                if valid:
                    area = (right - left) * (top - bottom)
                    if area > best:
                        best = area

        return best

