class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        pts = [tuple(p) for p in points]
        s = set(pts)
        n = len(pts)
        ans = -1

        for i in range(n):
            x1, y1 = pts[i]
            for j in range(i + 1, n):
                x2, y2 = pts[j]
                if x1 == x2 or y1 == y2:
                    continue  # cannot be diagonal of non-zero area rectangle
                lx, rx = (x1, x2) if x1 < x2 else (x2, x1)
                by, ty = (y1, y2) if y1 < y2 else (y2, y1)

                c1 = (lx, by)
                c2 = (lx, ty)
                c3 = (rx, by)
                c4 = (rx, ty)

                if c1 not in s or c2 not in s or c3 not in s or c4 not in s:
                    continue

                corners = {c1, c2, c3, c4}
                ok = True
                for x, y in pts:
                    if (x, y) in corners:
                        continue
                    if lx <= x <= rx and by <= y <= ty:
                        ok = False
                        break

                if ok:
                    area = (rx - lx) * (ty - by)
                    if area > ans:
                        ans = area

        return ans

